# Sam's round 4 battery. Each entry: id, sql (ChloeDB), duck (DuckDB, when the dialect differs), ordered (the ORDER BY is total), note.
Q = []
def q(id, sql, duck=None, ordered=True, note=""):
    Q.append(dict(id=id, sql=" ".join(sql.split()), duck=" ".join(duck.split()) if duck else None, ordered=ordered, note=note))

# ---- trips: 205,064 rows (more than 4,096: DataFusion) ----
q("t01_aggs", "SELECT COUNT(*), COUNT(passenger_count), COUNT(DISTINCT PULocationID), SUM(total_amount), AVG(trip_distance), MIN(fare_amount), MAX(fare_amount) FROM trips")
q("t02_group_nulls", "SELECT payment_type, COUNT(*) AS n, AVG(tip_amount) AS avg_tip FROM trips GROUP BY payment_type ORDER BY payment_type")
q("t03_having", "SELECT PULocationID, COUNT(*) AS n, ROUND(AVG(total_amount), 2) AS avg_total FROM trips GROUP BY PULocationID HAVING COUNT(*) > 1000 ORDER BY n DESC, PULocationID")
q("t04_join_group", "SELECT z.Borough, COUNT(*) AS n, SUM(t.total_amount) AS rev FROM trips t JOIN zones z ON t.PULocationID = z.LocationID GROUP BY z.Borough ORDER BY n DESC, z.Borough")
q("t05_two_left_joins", "SELECT pz.Zone AS pu, dz.Zone AS dz_, COUNT(*) AS n FROM trips t LEFT JOIN zones pz ON t.PULocationID = pz.LocationID LEFT JOIN zones dz ON t.DOLocationID = dz.LocationID GROUP BY pz.Zone, dz.Zone ORDER BY n DESC, pu, dz_ LIMIT 10")
q("t06_not_exists", "SELECT z.LocationID, z.Zone FROM zones z WHERE NOT EXISTS (SELECT 1 FROM trips t WHERE t.PULocationID = z.LocationID) ORDER BY z.LocationID")
q("t07_in_subquery", "SELECT COUNT(*) FROM trips WHERE PULocationID IN (SELECT LocationID FROM zones WHERE Borough = 'Manhattan')")
q("t08_date_trunc_day", "SELECT date_trunc('day', lpep_pickup_datetime) AS d, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= '2023-01-01' AND lpep_pickup_datetime < '2023-04-01' GROUP BY d ORDER BY d",
  duck="SELECT date_trunc('day', lpep_pickup_datetime) AS d, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= TIMESTAMP '2023-01-01' AND lpep_pickup_datetime < TIMESTAMP '2023-04-01' GROUP BY d ORDER BY d")
q("t09_extract_dow_hour", "SELECT EXTRACT(dow FROM lpep_pickup_datetime) AS dow, EXTRACT(hour FROM lpep_pickup_datetime) AS hr, COUNT(*) AS n FROM trips GROUP BY dow, hr ORDER BY dow, hr")
q("t10_month_outliers", "SELECT date_trunc('month', lpep_pickup_datetime) AS m, COUNT(*) AS n FROM trips GROUP BY m ORDER BY m")
q("t11_date_diff", "SELECT payment_type, AVG(date_diff('minute', lpep_pickup_datetime, lpep_dropoff_datetime)) AS mins FROM trips GROUP BY payment_type ORDER BY payment_type")
q("t12_window_running", "WITH daily AS (SELECT date_trunc('day', lpep_pickup_datetime) AS d, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= '2023-01-01' AND lpep_pickup_datetime < '2023-04-01' GROUP BY d) SELECT d, n, SUM(n) OVER (ORDER BY d) AS running, AVG(n) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7, n - LAG(n) OVER (ORDER BY d) AS chg FROM daily ORDER BY d",
  duck="WITH daily AS (SELECT date_trunc('day', lpep_pickup_datetime) AS d, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= TIMESTAMP '2023-01-01' AND lpep_pickup_datetime < TIMESTAMP '2023-04-01' GROUP BY d) SELECT d, n, SUM(n) OVER (ORDER BY d) AS running, AVG(n) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7, n - LAG(n) OVER (ORDER BY d) AS chg FROM daily ORDER BY d")
q("t13_rank_qualify", "WITH c AS (SELECT z.Borough AS b, t.DOLocationID AS loc, COUNT(*) AS n FROM trips t JOIN zones z ON t.PULocationID = z.LocationID GROUP BY z.Borough, t.DOLocationID) SELECT b, loc, n, RANK() OVER (PARTITION BY b ORDER BY n DESC) AS r FROM c QUALIFY ROW_NUMBER() OVER (PARTITION BY b ORDER BY n DESC, loc) <= 3 ORDER BY b, n DESC, loc")
q("t14_ntile_small", "SELECT trip_id, total_amount, NTILE(4) OVER (ORDER BY total_amount, trip_id) AS q4, ROW_NUMBER() OVER (ORDER BY total_amount DESC, trip_id) AS rn, PERCENT_RANK() OVER (ORDER BY total_amount) AS pr FROM trips WHERE PULocationID = 116 ORDER BY trip_id", note="2,285 rows")
q("t15_ntile_big", "SELECT q4, COUNT(*) AS n, MIN(total_amount) AS mn, MAX(total_amount) AS mx, SUM(rn) AS srn FROM (SELECT trip_id, total_amount, NTILE(4) OVER (ORDER BY total_amount, trip_id) AS q4, ROW_NUMBER() OVER (ORDER BY total_amount DESC, trip_id) AS rn FROM trips WHERE PULocationID = 74) w GROUP BY q4 ORDER BY q4", note="38,821 rows under the window")
q("t15b_rows_over_10000", "SELECT trip_id, total_amount, NTILE(4) OVER (ORDER BY total_amount, trip_id) AS q4 FROM trips WHERE PULocationID = 74 ORDER BY trip_id", note="38,821 rows out: over the server's 10,000-row window")
q("t16_case_bucket", "SELECT CASE WHEN trip_distance IS NULL THEN 'unknown' WHEN trip_distance < 1 THEN 'short' WHEN trip_distance < 5 THEN 'medium' ELSE 'long' END AS bucket, COUNT(*) AS n, AVG(tip_amount) AS tip FROM trips GROUP BY bucket ORDER BY bucket")
q("t17_filter_coalesce", "SELECT COUNT(*) FILTER (WHERE passenger_count IS NULL) AS nulls, COUNT(*) FILTER (WHERE passenger_count != 1) AS not1, SUM(COALESCE(passenger_count, 0)) AS s, AVG(COALESCE(passenger_count, 1)) AS a FROM trips")
q("t18_not_in_nulls", "SELECT (SELECT COUNT(*) FROM trips WHERE payment_type NOT IN (1, 2)) AS a, (SELECT COUNT(*) FROM trips WHERE payment_type NOT IN (1, NULL)) AS b, (SELECT COUNT(*) FROM trips WHERE NOT (payment_type = 1)) AS c")
q("t19_limit_offset", "SELECT trip_id, total_amount FROM trips ORDER BY total_amount DESC, trip_id LIMIT 10 OFFSET 20")
q("t20_distinct", "SELECT DISTINCT VendorID, payment_type FROM trips ORDER BY VendorID, payment_type")
q("t21_intersect", "SELECT PULocationID AS loc FROM trips WHERE lpep_pickup_datetime < '2023-01-02' INTERSECT SELECT DOLocationID FROM trips WHERE lpep_pickup_datetime < '2023-01-02' ORDER BY loc",
  duck="SELECT PULocationID AS loc FROM trips WHERE lpep_pickup_datetime < TIMESTAMP '2023-01-02' INTERSECT SELECT DOLocationID FROM trips WHERE lpep_pickup_datetime < TIMESTAMP '2023-01-02' ORDER BY loc")
q("t22_union_all_order", "SELECT trip_id, total_amount AS v FROM trips WHERE PULocationID = 196 UNION ALL SELECT trip_id, tip_amount FROM trips WHERE PULocationID = 33 ORDER BY v DESC, trip_id LIMIT 15")
q("t23_except", "SELECT DOLocationID AS loc FROM trips EXCEPT SELECT PULocationID FROM trips ORDER BY loc")
q("t24_scalar_subq", "SELECT COUNT(*) FROM trips WHERE total_amount > (SELECT AVG(total_amount) FROM trips)")
q("t25_percentiles", "SELECT payment_type, MEDIAN(total_amount) AS med, PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY total_amount) AS p90, PERCENTILE_DISC(0.9) WITHIN GROUP (ORDER BY total_amount) AS p90d FROM trips GROUP BY payment_type ORDER BY payment_type")
q("t26_stats", "SELECT VendorID, STDDEV(tip_amount) AS sd, VAR_POP(tip_amount) AS vp, CORR(tip_amount, fare_amount) AS r FROM trips GROUP BY VendorID ORDER BY VendorID")
q("t27_arith", "SELECT SUM(tip_amount) / SUM(fare_amount) AS ratio, 7 / 2 AS d, 7 % 2 AS m, ROUND(2.5) AS r, ROUND(AVG(fare_amount), 2) AS ra FROM trips")
q("t28_cast_round", "SELECT trip_id, CAST(trip_distance AS INT) AS ci, ROUND(trip_distance) AS r0, ROUND(trip_distance, 1) AS r1, floor(trip_distance) AS f, ceil(trip_distance) AS c FROM trips WHERE trip_id IN (1, 2, 3, 4, 5, 100, 1000, 5000) ORDER BY trip_id")
q("t29_strftime", "SELECT strftime('%Y-%m', lpep_pickup_datetime) AS ym, COUNT(*) AS n FROM trips GROUP BY ym ORDER BY ym",
  duck="SELECT strftime(lpep_pickup_datetime, '%Y-%m') AS ym, COUNT(*) AS n FROM trips GROUP BY ym ORDER BY ym")
q("t30_cte_chain", "WITH z AS (SELECT LocationID, Borough FROM zones), t AS (SELECT PULocationID, total_amount FROM trips WHERE total_amount > 50) SELECT z.Borough, COUNT(*) AS n, MAX(t.total_amount) AS mx FROM t JOIN z ON t.PULocationID = z.LocationID GROUP BY z.Borough ORDER BY z.Borough")
q("t31_derived", "SELECT b, n FROM (SELECT z.Borough AS b, COUNT(*) AS n FROM trips t JOIN zones z ON t.DOLocationID = z.LocationID GROUP BY z.Borough) AS x WHERE n > 1000 ORDER BY n DESC")
q("t32_full_join", "WITH pu AS (SELECT PULocationID AS loc, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime < '2023-01-08' GROUP BY PULocationID) SELECT z.LocationID, pu.loc, pu.n FROM zones z FULL JOIN pu ON z.LocationID = pu.loc ORDER BY z.LocationID NULLS FIRST, pu.loc",
  duck="WITH pu AS (SELECT PULocationID AS loc, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime < TIMESTAMP '2023-01-08' GROUP BY PULocationID) SELECT z.LocationID, pu.loc, pu.n FROM zones z FULL JOIN pu ON z.LocationID = pu.loc ORDER BY z.LocationID NULLS FIRST, pu.loc")
q("t33_self_join_ineq", "SELECT a.Borough, COUNT(*) AS pairs FROM zones a JOIN zones b ON a.Borough = b.Borough AND a.LocationID < b.LocationID GROUP BY a.Borough ORDER BY a.Borough")
q("t34_right_join", "SELECT z.Zone, t.n FROM (SELECT DOLocationID AS loc, COUNT(*) AS n FROM trips WHERE PULocationID = 196 GROUP BY DOLocationID) t RIGHT JOIN zones z ON t.loc = z.LocationID WHERE z.Borough = 'Staten Island' ORDER BY z.Zone")
q("t35_string_funcs", "SELECT LocationID, upper(Zone) AS u, lower(Borough) AS l, length(Zone) AS len, substr(Zone, 1, 5) AS s5, replace(Zone, '/', '-') AS rep, concat(Borough, ' - ', Zone) AS c, Borough || '/' || Zone AS p, trim('  x  ') AS tr FROM zones ORDER BY LocationID")
q("t36_like_ilike", "SELECT (SELECT COUNT(*) FROM zones WHERE Zone LIKE '%Park%') AS a, (SELECT COUNT(*) FROM zones WHERE Zone ILIKE '%park%') AS b, (SELECT COUNT(*) FROM zones WHERE Zone LIKE 'East%') AS c, (SELECT COUNT(*) FROM zones WHERE Zone NOT LIKE '%a%') AS d")
q("t37_group_expr", "SELECT substr(Zone, 1, 1) AS letter, COUNT(*) AS n FROM zones GROUP BY letter ORDER BY letter")
q("t38_string_agg", "SELECT Borough, STRING_AGG(service_zone, ',' ORDER BY service_zone) AS s, COUNT(DISTINCT service_zone) AS k FROM zones GROUP BY Borough ORDER BY Borough")
q("t39_exists_semi", "SELECT COUNT(*) FROM zones z WHERE EXISTS (SELECT 1 FROM trips t WHERE t.DOLocationID = z.LocationID AND t.total_amount > 200)")
q("t40_window_over_groups", "SELECT VendorID, COUNT(*) AS n, RANK() OVER (ORDER BY COUNT(*) DESC) AS r, COUNT(*) / SUM(COUNT(*)) OVER () AS share FROM trips GROUP BY VendorID ORDER BY VendorID")
q("t41_lead_default", "SELECT trip_id, total_amount, LEAD(total_amount, 1, 0) OVER (ORDER BY trip_id) AS nxt, FIRST_VALUE(total_amount) OVER (ORDER BY trip_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS fv FROM trips WHERE PULocationID = 196 ORDER BY trip_id LIMIT 20")
q("t42_interval", "SELECT COUNT(*) FROM trips WHERE lpep_pickup_datetime >= TIMESTAMP '2023-03-01' - INTERVAL '7 days' AND lpep_pickup_datetime < TIMESTAMP '2023-03-01'")
q("t43_date_bin", "SELECT date_bin('6 hours', lpep_pickup_datetime) AS b, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= '2023-02-01' AND lpep_pickup_datetime < '2023-02-03' GROUP BY b ORDER BY b",
  duck="SELECT time_bucket(INTERVAL '6 hours', lpep_pickup_datetime) AS b, COUNT(*) AS n FROM trips WHERE lpep_pickup_datetime >= TIMESTAMP '2023-02-01' AND lpep_pickup_datetime < TIMESTAMP '2023-02-03' GROUP BY b ORDER BY b")
q("t44_order_desc_nulls", "SELECT trip_id, passenger_count FROM trips WHERE PULocationID = 196 ORDER BY passenger_count DESC, trip_id LIMIT 5", note="Postgres would put NULLs first on DESC; DuckDB puts them last")
q("t45_count_distinct_two", "SELECT COUNT(*) FROM (SELECT DISTINCT PULocationID, DOLocationID FROM trips) d")

# ---- Chinook: small tables (fewer than 4,096 rows but PlaylistTrack, 8,715) ----
q("c01_top_artists", "SELECT ar.Name, COUNT(*) AS n FROM Track t JOIN Album al ON t.AlbumId = al.AlbumId JOIN Artist ar ON al.ArtistId = ar.ArtistId GROUP BY ar.Name ORDER BY n DESC, ar.Name LIMIT 5")
q("c02_country_having", "SELECT BillingCountry, SUM(Total) AS rev, COUNT(*) AS n FROM Invoice GROUP BY BillingCountry HAVING SUM(Total) > 100 ORDER BY rev DESC, BillingCountry")
q("c03_monthly_running", "WITH m AS (SELECT date_trunc('month', InvoiceDate) AS mo, SUM(Total) AS rev FROM Invoice GROUP BY mo) SELECT mo, rev, SUM(rev) OVER (ORDER BY mo) AS running FROM m ORDER BY mo")
q("c04_self_join_mgr", "SELECT e.EmployeeId, e.FirstName, m.FirstName AS mgr FROM Employee e LEFT JOIN Employee m ON e.ReportsTo = m.EmployeeId ORDER BY e.EmployeeId")
q("c05_top_genre_per_country", "WITH s AS (SELECT i.BillingCountry AS country, g.Name AS genre, SUM(il.UnitPrice * il.Quantity) AS rev FROM InvoiceLine il JOIN Invoice i ON il.InvoiceId = i.InvoiceId JOIN Track t ON il.TrackId = t.TrackId JOIN Genre g ON t.GenreId = g.GenreId GROUP BY i.BillingCountry, g.Name) SELECT country, genre, rev FROM s QUALIFY ROW_NUMBER() OVER (PARTITION BY country ORDER BY rev DESC, genre) = 1 ORDER BY country")
q("c06_never_bought", "SELECT COUNT(*) FROM Track t WHERE NOT EXISTS (SELECT 1 FROM InvoiceLine il WHERE il.TrackId = t.TrackId)")
q("c07_playlist_counts", "SELECT p.Name, COUNT(*) AS n FROM PlaylistTrack pt JOIN Playlist p ON pt.PlaylistId = p.PlaylistId GROUP BY p.Name ORDER BY n DESC, p.Name", note="8,715 rows")
q("c08_string_agg_customers", "SELECT Country, STRING_AGG(FirstName, ',' ORDER BY FirstName) AS names, COUNT(*) AS n FROM Customer GROUP BY Country ORDER BY Country")
q("c09_genre_stats", "SELECT g.Name, AVG(t.Milliseconds) / 60000.0 AS avg_min, COUNT(t.Composer) AS with_comp, COUNT(*) - COUNT(t.Composer) AS no_comp FROM Track t JOIN Genre g ON t.GenreId = g.GenreId GROUP BY g.Name ORDER BY g.Name")
q("c10_dense_rank_spend", "WITH s AS (SELECT CustomerId, SUM(Total) AS spend FROM Invoice GROUP BY CustomerId) SELECT c.CustomerId, c.LastName, s.spend, DENSE_RANK() OVER (ORDER BY s.spend DESC) AS dr FROM s JOIN Customer c ON s.CustomerId = c.CustomerId ORDER BY s.spend DESC, c.CustomerId LIMIT 10")
q("c11_year", "SELECT EXTRACT(year FROM InvoiceDate) AS y, COUNT(*) AS n, SUM(Total) AS rev FROM Invoice GROUP BY y ORDER BY y")
q("c12_lag_gap", "SELECT CustomerId, InvoiceDate, date_diff('day', LAG(InvoiceDate) OVER (PARTITION BY CustomerId ORDER BY InvoiceDate), InvoiceDate) AS gap FROM Invoice WHERE CustomerId <= 3 ORDER BY CustomerId, InvoiceDate")
q("c13_exists_2", "SELECT c.CustomerId, c.LastName FROM Customer c WHERE EXISTS (SELECT 1 FROM Invoice i WHERE i.CustomerId = c.CustomerId AND i.Total > 20) ORDER BY c.CustomerId")
q("c14_text_group", "SELECT mt.Name, COUNT(*) AS n, SUM(t.Bytes) AS bytes FROM Track t JOIN MediaType mt ON t.MediaTypeId = mt.MediaTypeId GROUP BY mt.Name ORDER BY n DESC")
q("c15_like_text", "SELECT COUNT(*) FROM Track WHERE Name LIKE '%Love%'")
q("c16_in_list_case", "SELECT CASE WHEN GenreId IN (1, 3) THEN 'rock/metal' WHEN GenreId = 2 THEN 'jazz' ELSE 'other' END AS g, COUNT(*) AS n, MIN(Milliseconds) AS mn FROM Track GROUP BY g ORDER BY g")
q("c17_three_table_left", "SELECT a.Title, COUNT(t.TrackId) AS n FROM Album a LEFT JOIN Track t ON t.AlbumId = a.AlbumId GROUP BY a.Title ORDER BY n DESC, a.Title LIMIT 8")
q("c18_employee_ages", "SELECT LastName, date_diff('year', BirthDate, HireDate) AS age_at_hire, EXTRACT(month FROM HireDate) AS hm FROM Employee ORDER BY EmployeeId")

# ---- things the docs say are refused; we record the error ----
q("x01_recursive_cte", "WITH RECURSIVE chain AS (SELECT EmployeeId, ReportsTo, 0 AS depth FROM Employee WHERE ReportsTo IS NULL UNION ALL SELECT e.EmployeeId, e.ReportsTo, c.depth + 1 FROM Employee e JOIN chain c ON e.ReportsTo = c.EmployeeId) SELECT EmployeeId, depth FROM chain ORDER BY EmployeeId")
q("x02_rollup", "SELECT Borough, service_zone, COUNT(*) AS n FROM zones GROUP BY ROLLUP (Borough, service_zone) ORDER BY Borough NULLS LAST, service_zone NULLS LAST")
q("x03_grouping_sets", "SELECT Borough, service_zone, COUNT(*) AS n FROM zones GROUP BY GROUPING SETS ((Borough), (service_zone)) ORDER BY Borough NULLS LAST, service_zone NULLS LAST")
q("x04_is_distinct", "SELECT COUNT(*) FROM trips WHERE payment_type IS DISTINCT FROM 1")
q("x05_cross_join", "SELECT COUNT(*) FROM zones a CROSS JOIN (SELECT DISTINCT VendorID FROM trips) v")
q("x06_using", "SELECT COUNT(*) FROM Track JOIN Album USING (AlbumId)")
q("x07_comma_join", "SELECT COUNT(*) FROM Track t, Album a WHERE t.AlbumId = a.AlbumId")
q("x08_keyword_range", "SELECT COUNT(*) FROM zones WHERE Borough BETWEEN 'A' AND 'M'")
q("x09_sum_distinct", "SELECT SUM(DISTINCT payment_type) FROM trips")
q("x10_json_arrow", "SELECT json_extract('{\"a\": {\"b\": 2}}', '$.a.b') AS v", duck="SELECT json_extract('{\"a\": {\"b\": 2}}', '$.a.b')::INT AS v")
